"""Print the UnicodeData.txt line of every character on the deck's fronts."""
import pathlib
HERE = pathlib.Path(__file__).parent
fronts = "∀ ∃ ¬ ∧ ∨ ⇒ ⇔ ∈ ∉ ∅ ⊆ ⊂ ⊊ ∪ ∩ ∖ ℕ ℤ ℚ ℝ ℜ ℂ ≠ ≈ ∝ ≤ ≥ ≡ ∣ | ∥ ∠ ∑ ∏ √ ± ⌊ ⌋ ⌈ ⌉ ! ∘ ∫ ∂ ∇ π e i ∞ ⊥ ⟂".split()
data = {}
for line in (HERE / "UnicodeData.txt").read_text().splitlines():
    f = line.split(";")
    data[int(f[0], 16)] = line
for ch in fronts:
    print(ch, data[ord(ch)])
